import {FormControl} from '@primer/react'

import type {ValidationKind} from '../helpers/validation'
import styles from './FormValidationNode.module.css'

export function FormValidationNode({id, item}: {item: ValidationKind | undefined; id?: string}) {
  if (!item) return null

  let variant: 'success' | 'error' | null = null
  if ('success' in item) variant = 'success'
  if ('error' in item) variant = 'error'
  if (!variant) return null

  return (
    <div className={styles.Validation}>
      <FormControl.Validation id={id} variant={variant}>
        {item[variant]}
      </FormControl.Validation>
    </div>
  )
}
