import {TriangleDownIcon} from '@primer/octicons-react'
import {Button, SelectPanel} from '@primer/react'
import {type ComponentProps, type ElementType, type PropsWithChildren, useCallback, useMemo, useState} from 'react'

import {getProviderFor, type Provider, type ProviderItem} from './config'
import {ProviderLogo} from './ProviderLogo'

type SelectPanelItem = {
  id: Provider
  text: string
  leadingVisual?: ElementType
}

export function ProviderPicker({
  id,
  selected,
  onSelected,
  disabled,
  providers,
}: {
  id?: string
  onSelected?: (provider: Provider) => void
  providers: readonly Provider[]
  selected?: Provider
  disabled?: boolean
}) {
  const [showPanel, setShowPanel] = useState(false)

  const [filter, setFilter] = useState('')

  const items = useMemo<SelectPanelItem[]>(() => {
    const filterValue = filter.toLowerCase()
    const sortedProviders = providers.toSorted((a, b) => {
      const providerA = getProviderFor(a)
      const providerB = getProviderFor(b)
      return providerA.name.toLocaleLowerCase().localeCompare(providerB.name.toLocaleLowerCase())
    })
    return sortedProviders.flatMap(item => {
      const provider = getProviderFor(item)
      if (filterValue && !provider.name.toLowerCase().includes(filterValue)) return []
      return [selectPanelItemFromProvider(provider)]
    })
  }, [filter, providers])

  const onSelectedChange = useCallback(
    (item: {id?: unknown} | undefined) => {
      if (!item?.id) return
      onSelected?.(item.id as Provider)
    },
    [onSelected],
  )

  const selectedItem = useMemo(() => {
    if (!selected) return undefined
    return selectPanelItemFromProvider(getProviderFor(selected))
  }, [selected])

  // SelectPanel doesn't currently support being disabled, so we just customize the anchor
  // https://github.com/primer/react/blob/0e04210b4b257edf88dbd6e808a472703855fd54/packages/react/src/SelectPanel/SelectPanel.tsx#L144-L151
  const renderAnchor = useCallback(
    (props: PropsWithChildren<ComponentProps<typeof Button>>) => {
      const {children, ...rest} = props

      const leadingVisual = selected && <ProviderLogo provider={selected} size="small" />

      return (
        <Button trailingAction={TriangleDownIcon} {...rest} disabled={disabled} leadingVisual={leadingVisual}>
          {children}
        </Button>
      )
    },
    [disabled, selected],
  )

  return (
    <SelectPanel
      id={id}
      title="Select provider"
      placeholder="Select provider"
      placeholderText="Search"
      renderAnchor={renderAnchor}
      items={items}
      open={showPanel}
      onOpenChange={setShowPanel}
      onFilterChange={setFilter}
      selected={selectedItem}
      onSelectedChange={onSelectedChange}
      overlayProps={{width: 'medium', height: 'auto'}}
      textInputProps={{
        ['aria-label']: 'Filter providers',
      }}
      message={
        items.length === 0
          ? {
              title: 'No providers found',
              body: 'Please refine your search to find a provider.',
              variant: 'empty',
            }
          : undefined
      }
    />
  )
}

function selectPanelItemFromProvider(item: ProviderItem): SelectPanelItem {
  return {
    id: item.key,
    text: item.name,
    leadingVisual() {
      return <ProviderLogo provider={item.key} size="small" />
    },
  }
}
