import {isResponseError} from '@github-ui/react-core/future/response-error'

export async function getErrorMessageFromResponse(error: Error) {
  if (isResponseError(error)) {
    return getMaybeJSONErrorMessage(error.response)
  }
  return null
}

export async function getMaybeJSONErrorMessage(response: Response) {
  let message: string | null = null

  // Don't try to clone the response if the body has already been used, otherwise an error will throw:
  if (response.bodyUsed) return message

  try {
    // We need to clone the response because they can only be read once.
    // and we don't know if somebody else has already read it.
    const res = response.clone()
    const json = await res.json()
    if (typeof json.message === 'string') {
      message = json.message
    }
  } catch {
    // Empty on purpose
  }
  return message
}
