import * as z from 'zod'

export type ValidationKind = {error?: string; success?: string}

export function validationKindFromZodError(error: z.ZodError): Record<string, ValidationKind> {
  const errors = z.treeifyError(error) as {
    properties?: Record<
      string,
      {
        items?: Array<{errors?: string[]; properties?: Record<string, {errors?: string[]}>}>
        errors?: string[]
        properties?: Record<string, {errors?: string[]}>
      }
    >
  }

  if (!errors.properties) return {}

  const result: Record<string, ValidationKind> = {}
  for (const key in errors.properties) {
    const value = errors.properties[key]
    if (!value) continue

    const errorMessage = value.errors?.[0]
    if (errorMessage) result[key] = {error: errorMessage}

    if (value.properties) {
      for (const nestedKey in value.properties) {
        const nestedValue = value.properties[nestedKey]
        if (nestedValue) {
          const nestedErrorMessage = nestedValue.errors?.[0]
          // e.g., 'provider_data.region': {error: 'Region is required'}
          if (nestedErrorMessage) result[`${key}.${nestedKey}`] = {error: nestedErrorMessage}
        }
      }
    }

    if (value.items) {
      for (let i = 0; i < value.items.length; i++) {
        const item = value.items[i]
        if (item && item.properties) {
          for (const nestedItemKey in item.properties) {
            const nestedItemValue = item.properties[nestedItemKey]
            if (nestedItemValue) {
              const nestedItemErrorMessage = nestedItemValue.errors?.[0]
              // e.g., 'models[0].id': {error: 'Invalid input: expected number, received null'}
              if (nestedItemErrorMessage) result[`${key}[${i}].${nestedItemKey}`] = {error: nestedItemErrorMessage}
            }
          }
        }
      }
    }
  }
  return result
}

export function getGeneralValidationKind(
  error: Error | string | null,
  fallback = 'An unexpected error occurred. Please try again later.',
) {
  const errorMessage = error instanceof Error ? error.message : error
  return {__general: {error: errorMessage || fallback}}
}
