import {encrypt} from '@github-ui/encryption'
import {encode} from '@github-ui/encryption/utils'
import {useCallback, useState} from 'react'

export function useAPIKey(publicKey: string) {
  const [apiKey, setApiKey] = useState<string | undefined>()

  return [
    apiKey,
    useCallback(
      async (value: string | undefined) => {
        if (value == null) return void setApiKey(undefined)

        if (value.length > 2) {
          setApiKey(encode(await encrypt(publicKey, value)))
        } else {
          setApiKey(undefined)
        }
      },
      [publicKey],
    ),
  ] as const
}
