import {FormControl, Link, Stack, TextInput} from '@primer/react'
import {type Dispatch, type SetStateAction, useId, useState} from 'react'
import * as z from 'zod'

import {useAPIKey} from '../../../hooks/use-api-key'
import type {ProviderDataFor, SelectorCustomModel} from '../../../types'
import styles from '../../AddEditDialog.module.css'
import {FormValidationNode} from '../../FormValidationNode'
import {ProviderModelSelectorPane} from '../ProviderModelSelectorPane'
import type {ProviderFieldProps} from '../types'

export function awsBedrockFormSchemaPreprocessor(payload: Record<string, unknown>) {
  const providerData: Record<string, unknown> = {}
  if ('region' in payload && typeof payload.region === 'string' && payload.region.trim().length > 0) {
    providerData.region = payload.region.trim()
  }
  payload.provider_data = providerData
  return payload
}

// What our backend endpoint expects when we try to create a new custom key and model(s) for it:
export const awsBedrockFormSchema = {
  provider: z.literal('awsbedrock'),
  // When editing an existing custom key, the region is already stored and doesn't need to be re-submitted:
  provider_data: z.object({region: z.string('Region is required').min(1, 'Region cannot be blank')}).optional(),
  access_key: z.string().nullish(),
  models: z.preprocess(
    modelsPreprocessor,
    z
      .array(
        z.union([
          // When updating a custom key and preserving existing model selections:
          z.object({
            id: z.number('Model ID is required'),
            slug: z.string().nullish(),
            name: z.string().nullish(),
          }),

          // When creating a custom key and selecting initial models:
          z.object({
            slug: z.string('Model slug is required').min(1, 'Model slug cannot be blank'),
            name: z.string().nullish(),
            maxOutputTokens: z.number().nullish(),
            provider_data: z.union([
              z.object({
                inference_type: z.literal('INFERENCE_PROFILE'),
                model_arn: z
                  .string('Model Amazon Resource Name (ARN) is required')
                  .min(1, 'Model Amazon Resource Name (ARN) cannot be blank'),
                inference_policy_arn: z
                  .string('Inference policy Amazon Resource Name (ARN) is required')
                  .min(1, 'Inference policy Amazon Resource Name (ARN) cannot be blank'),
                inference_policy_regions: z
                  .array(
                    z.string('Inference policy region is required').min(1, 'Inference policy region cannot be blank'),
                  )
                  .min(1, 'At least one inference policy region is required'),
              }),
              z.object({
                inference_type: z.literal('ON_DEMAND'),
                model_arn: z
                  .string('Model Amazon Resource Name (ARN) is required')
                  .min(1, 'Model Amazon Resource Name (ARN) cannot be blank'),
              }),
            ]),
          }),
        ]),
      )
      .min(1, 'Please select a model'),
  ),
} as const

const randomAccessKey = '*'.repeat(20)

export function AwsBedrockFields({
  apiKey,
  publicKey,
  customKey,
  validation,
  isPending,
  setValidation,
  onSetAdditionalData,
}: ProviderFieldProps<'awsbedrock'>) {
  const id = useId()
  const [accessKey, setAccessKey] = useAPIKey(publicKey || '')
  const [region, setRegion] = useState((customKey && customKey?.region) ?? 'us-west-2')
  const modelSelectorId = `${id}-model-selector`
  const ariaDescribedBy = `${id}-description`
  const providerData: ProviderDataFor<'awsbedrock'> = {
    provider: 'awsbedrock',
    accessKey: accessKey || '',
    region: region || '',
  }

  return (
    <>
      <AwsAccessKeyField
        setAccessKey={setAccessKey}
        isPending={isPending}
        customKey={customKey}
        validation={validation}
      />
      <AwsRegionField isPending={isPending} region={region} setRegion={setRegion} validation={validation} />
      <Stack.Item grow className={styles.ModelSelectorLayout}>
        <FormControl className="width-full" disabled={isPending}>
          <FormControl.Label htmlFor={modelSelectorId}>Available models</FormControl.Label>
          <ProviderModelSelectorPane
            provider="awsbedrock"
            customKeyId={customKey?.id}
            key={`awsbedrock-${apiKey}`}
            apiKey={apiKey}
            providerData={providerData}
            isPending={isPending}
            htmlForId={modelSelectorId}
            aria-describedby={ariaDescribedBy}
            setValidation={setValidation}
            onSetAdditionalData={onSetAdditionalData}
          />
          <FormValidationNode item={validation?.models} id={ariaDescribedBy} />
        </FormControl>
      </Stack.Item>
    </>
  )
}

/**
 * Renders a form field for the user to provide their AWS access key, in either
 * an organization or an enterprise context.
 */
export function AwsAccessKeyField({
  customKey,
  isPending,
  setAccessKey,
  validation,
}: Pick<ProviderFieldProps<'awsbedrock'>, 'customKey' | 'isPending' | 'validation'> & {
  setAccessKey: (value: string | undefined) => Promise<undefined>
}) {
  const accessKeyValidationId = useId()
  const [accessKeyInput, setAccessKeyInput] = useState(customKey ? randomAccessKey : '')

  return (
    <FormControl required disabled={isPending}>
      <FormControl.Label>Access key</FormControl.Label>
      <TextInput
        name="access_key"
        data-1p-ignore
        type="password"
        autoComplete="new-password"
        className="width-full"
        aria-describedby={accessKeyValidationId}
        value={accessKeyInput}
        onChange={e => setAccessKeyInput(e.currentTarget.value)}
        onBlur={e => setAccessKey(e.currentTarget.value)}
      />
      <FormValidationNode item={validation?.access_key} id={accessKeyValidationId} />
    </FormControl>
  )
}

export function AwsRegionField({
  isPending,
  region,
  setRegion,
  validation,
}: Pick<ProviderFieldProps<'awsbedrock'>, 'isPending' | 'validation'> & {
  region: string | undefined
  setRegion: Dispatch<SetStateAction<string>>
}) {
  const regionValidationId = useId()

  return (
    <FormControl required disabled={isPending}>
      <FormControl.Label>AWS region</FormControl.Label>
      <TextInput
        name="region"
        type="text"
        className="width-full"
        aria-describedby={regionValidationId}
        value={region || ''}
        placeholder="e.g., us-west-2"
        onChange={e => setRegion(e.currentTarget.value)}
      />
      <FormControl.Caption>
        Specify the{' '}
        <Link inline href="https://aws.amazon.com/about-aws/global-infrastructure/regions_az/">
          AWS region
        </Link>{' '}
        to look up models.
      </FormControl.Caption>
      <FormValidationNode item={validation ? validation['provider_data.region'] : undefined} id={regionValidationId} />
    </FormControl>
  )
}

function modelsPreprocessor(models: SelectorCustomModel[]) {
  return models.map(model => {
    const providerData = model.additionalData
    const modelForServerRequest: Record<string, unknown> = {slug: model.slug, name: model.name}
    if (typeof model.id === 'number') modelForServerRequest.id = model.id
    if (providerData) {
      modelForServerRequest.provider_data = {
        inference_type: providerData.inferenceType,
        model_arn: providerData.modelArn,
        inference_policy_arn: providerData.inferencePolicyArn,
        inference_policy_regions: providerData.inferencePolicyRegions,
      }
    }
    if (typeof model.maxOutputTokens === 'number') {
      modelForServerRequest.maxOutputTokens = model.maxOutputTokens
    }
    return modelForServerRequest
  })
}
